import sys
sys.path.insert(0, '.')
from src.entry_reasoning_pipeline import _restrict_to_chains
from collections import deque

call_graph = {
    'A': ['B'],
    'B': ['C'],
    'D': ['C'],
}
end_funcs = ['C']

if not end_funcs:
    print('end_funcs is falsy')
else:
    print('end_funcs truthy, len=', len(end_funcs))
    callers = {fqn: set() for fqn in call_graph}
    print('initial callers:', callers)
    for fqn, callees in call_graph.items():
        for callee in callees:
            callers.setdefault(callee, set()).add(fqn)
    print('filled callers:', callers)

    on_chain = set()
    queue = deque(ef for ef in end_funcs if ef in call_graph)
    print('initial queue:', list(queue))
    while queue:
        fqn = queue.popleft()
        print('  processing:', fqn)
        if fqn in on_chain:
            print('    already in on_chain')
            continue
        on_chain.add(fqn)
        for caller in callers.get(fqn, ()):
            if caller not in on_chain:
                queue.append(caller)
                print('    added to queue:', caller)
    print('on_chain:', on_chain)

    end_set = set(end_funcs)
    pruned = {}
    for fqn in on_chain:
        if fqn in end_set:
            pruned[fqn] = []
        else:
            pruned[fqn] = [c for c in call_graph[fqn] if c in on_chain]
    print('pruned:', pruned)

print('function result:', _restrict_to_chains(call_graph, 'A', ['C']))
" 2>&1"}

